200	    `[ASSUMMPTION: kein dedizierter --color-on-success-container-Token in _tokens.scss vorhanden (nur --color-success-container ohne passenden Text-Token) — --color-on-surface als ausreichend kontrastreicher Text auf der hellen success-container-Fläche verwendet, keine neuen Tokens einführen, da DESIGN.md badge-status nur background+radius definiert]`
201	  - [ ] `badge-status.spec.ts`: Text „aktiv" bei `status = 'Aktiv'`, Text „storniert" bei `status = 'Storniert'`, jeweils passende Modifier-Klasse gesetzt (Muster: `buchungsreferenz.spec.ts`, `fixture.componentRef.setInput('status', ...)`).
202	
203	- [ ] Task 6: Frontend — `BuchungAbrufen`-Formular-Komponente (AC: #3, #7)
204	  - [ ] Neue Komponente `seed-a-frontend/src/app/buchung-abrufen/buchung-abrufen.ts` (+ `.html`, `.scss`, `.spec.ts`), Selector `app-buchung-abrufen`, ein Eingabefeld + Submit-Button:
205	    ```typescript
206	    import { Component, DestroyRef, inject, signal } from '@angular/core';
207	    import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
208	    import { Router } from '@angular/router';
209	    import { BuchungenService } from '../shared/api/buchungen.service';
210	
211	    @Component({
212	      selector: 'app-buchung-abrufen',
213	      imports: [],
214	      templateUrl: './buchung-abrufen.html',
215	      styleUrl: './buchung-abrufen.scss',
216	    })
217	    export class BuchungAbrufen {
218	      private readonly buchungenService = inject(BuchungenService);
219	      private readonly router = inject(Router);
220	      private readonly destroyRef = inject(DestroyRef);
221	
222	      readonly referenzEingabe = signal('');
223	      readonly laedt = signal(false);
224	      readonly fehler = signal<string | null>(null);
225	
226	      protected absenden(): void {
227	        const referenz = this.referenzEingabe().trim();
228	        if (!referenz || this.laedt()) return;
229	
230	        this.laedt.set(true);
231	        this.fehler.set(null);
232	
233	        this.buchungenService
234	          .buchungAbrufen(referenz)
235	          .pipe(takeUntilDestroyed(this.destroyRef))
236	          .subscribe({
237	            next: () => {
238	              this.laedt.set(false);
239	              this.router.navigate(['/buchungen', referenz]);
240	            },
241	            error: () => {
242	              this.laedt.set(false);
243	              this.fehler.set('Keine Buchung mit dieser Referenz gefunden.');
244	            },
245	          });
246	      }
247	    }
248	    ```
249	    **Warum hier bereits ein GET erfolgt statt nur zu navigieren:** `EXPERIENCE.md` State Patterns weist „Referenz nicht gefunden" explizit der Surface „Buchung abrufen" zu (nicht der Buchungsdetailseite) — der Fehlerfall muss auf dieser Seite sichtbar werden, ohne dass der Besucher zwischenzeitlich auf eine andere Route wechselt. Bei Erfolg wird zur Buchungsdetailseite navigiert, die den Datensatz über denselben Endpunkt selbst erneut lädt (kein Weiterreichen der Daten über Router-State nötig — `Buchungsdetail` muss ohnehin direkt aufrufbar/neu ladbar sein, siehe Task 7).
250	    ```html
251	    <!-- buchung-abrufen.html -->
252	    <main class="buchung-abrufen">
253	      <h1 class="buchung-abrufen__titel">Buchung abrufen</h1>
254	      @if (fehler(); as f) {
255	        <div class="banner-error" role="alert">{{ f }}</div>
256	      }
257	      <form class="buchung-abrufen__formular" (submit)="$event.preventDefault(); absenden()">
258	        <label class="buchung-abrufen__label" for="referenz-eingabe">Buchungsreferenz</label>
259	        <input
260	          id="referenz-eingabe"
261	          class="buchung-abrufen__input"
262	          type="text"
263	          autocomplete="off"
264	          [value]="referenzEingabe()"
265	          (input)="referenzEingabe.set($any($event.target).value)"
266	        />
267	        <button
268	          type="submit"
269	          class="buchung-abrufen__absenden"
270	          [disabled]="laedt() || referenzEingabe().trim().length === 0"
271	          [attr.aria-busy]="laedt()"
272	        >
273	          {{ laedt() ? 'Wird gesucht…' : 'Buchung abrufen' }}
274	        </button>
275	      </form>
276	    </main>
277	    ```
278	  - [ ] `buchung-abrufen.spec.ts` (Muster: `veranstaltungsdetail.spec.ts` — `TestBed` + Service-Stub, `provideRouter([])`): Submit-Button bei leerem Feld deaktiviert; bei Fehlschlag (`error: () => throwError(...)`) erscheint `banner-error` mit exaktem Text „Keine Buchung mit dieser Referenz gefunden."; bei Erfolg wird `Router.navigate` mit `['/buchungen', <referenz>]` aufgerufen (`vi.spyOn(TestBed.inject(Router), 'navigate')`).
279	
280	- [ ] Task 7: Frontend — `Buchungsdetail`-Anzeige-Komponente (AC: #1, #2, #4, #5, #6)
281	  - [ ] Neue Komponente `seed-a-frontend/src/app/buchung-abrufen/buchungsdetail.ts` (+ `.html`, `.scss`, `.spec.ts`), Selector `app-buchungsdetail`. 1:1 dasselbe Lade-Muster wie `veranstaltungsdetail.ts` (Story 1.4): `ActivatedRoute.paramMap` → `switchMap` → Service-Call → `catchError` setzt Fehlerzustand:
282	    ```typescript
283	    import { CurrencyPipe, DatePipe } from '@angular/common';
284	    import { Component, inject, signal } from '@angular/core';
285	    import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
286	    import { ActivatedRoute } from '@angular/router';
287	    import { EMPTY, catchError, map, switchMap } from 'rxjs';
288	    import { BuchungenService } from '../shared/api/buchungen.service';
289	    import { BuchungDetail } from '../shared/models/buchung-detail';
290	    import { BadgeStatus } from '../shared/ui/badge-status/badge-status';
291	    import { Buchungsreferenz } from '../shared/ui/buchungsreferenz/buchungsreferenz';
292	    import { spielstaettenOffset } from '../shared/utils/zeitzone';
293	
294	    type Ladezustand = 'laedt' | 'geladen' | 'fehler';
295	
296	    @Component({
297	      selector: 'app-buchungsdetail',
298	      imports: [CurrencyPipe, DatePipe, BadgeStatus, Buchungsreferenz],
299	      templateUrl: './buchungsdetail.html',
300	      styleUrl: './buchungsdetail.scss',
301	    })
302	    export class Buchungsdetail {
303	      private readonly buchungenService = inject(BuchungenService);
304	      private readonly route = inject(ActivatedRoute);
305	
306	      readonly ladezustand = signal<Ladezustand>('laedt');
307	      readonly buchung = signal<BuchungDetail | null>(null);
308	
309	      protected readonly spielstaettenOffset = spielstaettenOffset;
310	
311	      constructor() {
312	        this.route.paramMap
313	          .pipe(
314	            map((paramMap) => paramMap.get('referenz')!),
315	            switchMap((referenz) => {
316	              this.ladezustand.set('laedt');
317	              return this.buchungenService.buchungAbrufen(referenz).pipe(
318	                catchError(() => {
319	                  this.ladezustand.set('fehler');
320	                  return EMPTY;
321	                }),
322	              );
323	            }),
324	            takeUntilDestroyed(),
325	          )
326	          .subscribe((buchung) => {
327	            this.buchung.set(buchung);
328	            this.ladezustand.set('geladen');
329	          });
330	      }
331	    }
332	    ```
333	    ```html
334	    <!-- buchungsdetail.html -->
335	    @if (ladezustand() === 'laedt') {
336	      <p class="buchungsdetail__ladehinweis">Buchung wird geladen …</p>
337	    } @else if (ladezustand() === 'fehler') {
338	      <p class="buchungsdetail__fehler" role="alert">
339	        Keine Buchung mit dieser Referenz gefunden.
