2	
3	@Component({
4	  selector: 'app-buchungsreferenz',
5	  imports: [],
6	  templateUrl: './buchungsreferenz.html',
7	  styleUrl: './buchungsreferenz.scss',
8	})
9	export class Buchungsreferenz {
10	  readonly referenz = input.required<string>();
11	
12	  protected readonly kopiert = signal(false);
13	
14	  protected async kopieren(): Promise<void> {
15	    try {
16	      await navigator.clipboard.writeText(this.referenz());
17	      this.kopiert.set(true);
18	      setTimeout(() => this.kopiert.set(false), 2000);
19	    } catch {
20	      // Clipboard-API kann in unsicheren Kontexten/älteren Browsern fehlen — die Referenz
