    `[ASSUMMPTION: kein dedizierter --color-on-success-container-Token in _tokens.scss vorhanden (nur --color-success-container ohne passenden Text-Token) — --color-on-surface als ausreichend kontrastreicher Text auf der hellen success-container-Fläche verwendet, keine neuen Tokens einführen, da DESIGN.md badge-status nur background+radius definiert]`
  - [ ] `badge-status.spec.ts`: Text „aktiv" bei `status = 'Aktiv'`, Text „storniert" bei `status = 'Storniert'`, jeweils passende Modifier-Klasse gesetzt (Muster: `buchungsreferenz.spec.ts`, `fixture.componentRef.setInput('status', ...)`).

- [ ] Task 6: Frontend — `BuchungAbrufen`-Formular-Komponente (AC: #3, #7)
  - [ ] Neue Komponente `seed-a-frontend/src/app/buchung-abrufen/buchung-abrufen.ts` (+ `.html`, `.scss`, `.spec.ts`), Selector `app-buchung-abrufen`, ein Eingabefeld + Submit-Button:
    ```typescript
    import { Component, DestroyRef, inject, signal } from '@angular/core';
    import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
    import { Router } from '@angular/router';
    import { BuchungenService } from '../shared/api/buchungen.service';

    @Component({
      selector: 'app-buchung-abrufen',
      imports: [],
      templateUrl: './buchung-abrufen.html',
      styleUrl: './buchung-abrufen.scss',
    })
    export class BuchungAbrufen {
      private readonly buchungenService = inject(BuchungenService);
      private readonly router = inject(Router);
      private readonly destroyRef = inject(DestroyRef);

      readonly referenzEingabe = signal('');
      readonly laedt = signal(false);
      readonly fehler = signal<string | null>(null);

      protected absenden(): void {
        const referenz = this.referenzEingabe().trim();
        if (!referenz || this.laedt()) return;

        this.laedt.set(true);
        this.fehler.set(null);

        this.buchungenService
          .buchungAbrufen(referenz)
          .pipe(takeUntilDestroyed(this.destroyRef))
          .subscribe({
            next: () => {
              this.laedt.set(false);
              this.router.navigate(['/buchungen', referenz]);
            },
            error: () => {
              this.laedt.set(false);
              this.fehler.set('Keine Buchung mit dieser Referenz gefunden.');
            },
          });
      }
    }
    ```
    **Warum hier bereits ein GET erfolgt statt nur zu navigieren:** `EXPERIENCE.md` State Patterns weist „Referenz nicht gefunden" explizit der Surface „Buchung abrufen" zu (nicht der Buchungsdetailseite) — der Fehlerfall muss auf dieser Seite sichtbar werden, ohne dass der Besucher zwischenzeitlich auf eine andere Route wechselt. Bei Erfolg wird zur Buchungsdetailseite navigiert, die den Datensatz über denselben Endpunkt selbst erneut lädt (kein Weiterreichen der Daten über Router-State nötig — `Buchungsdetail` muss ohnehin direkt aufrufbar/neu ladbar sein, siehe Task 7).
    ```html
    <!-- buchung-abrufen.html -->
    <main class="buchung-abrufen">
      <h1 class="buchung-abrufen__titel">Buchung abrufen</h1>
      @if (fehler(); as f) {
        <div class="banner-error" role="alert">{{ f }}</div>
      }
      <form class="buchung-abrufen__formular" (submit)="$event.preventDefault(); absenden()">
        <label class="buchung-abrufen__label" for="referenz-eingabe">Buchungsreferenz</label>
        <input
          id="referenz-eingabe"
          class="buchung-abrufen__input"
          type="text"
          autocomplete="off"
          [value]="referenzEingabe()"
          (input)="referenzEingabe.set($any($event.target).value)"
        />
        <button
          type="submit"
          class="buchung-abrufen__absenden"
          [disabled]="laedt() || referenzEingabe().trim().length === 0"
          [attr.aria-busy]="laedt()"
        >
          {{ laedt() ? 'Wird gesucht…' : 'Buchung abrufen' }}
        </button>
      </form>
    </main>
    ```
  - [ ] `buchung-abrufen.spec.ts` (Muster: `veranstaltungsdetail.spec.ts` — `TestBed` + Service-Stub, `provideRouter([])`): Submit-Button bei leerem Feld deaktiviert; bei Fehlschlag (`error: () => throwError(...)`) erscheint `banner-error` mit exaktem Text „Keine Buchung mit dieser Referenz gefunden."; bei Erfolg wird `Router.navigate` mit `['/buchungen', <referenz>]` aufgerufen (`vi.spyOn(TestBed.inject(Router), 'navigate')`).

- [ ] Task 7: Frontend — `Buchungsdetail`-Anzeige-Komponente (AC: #1, #2, #4, #5, #6)
  - [ ] Neue Komponente `seed-a-frontend/src/app/buchung-abrufen/buchungsdetail.ts` (+ `.html`, `.scss`, `.spec.ts`), Selector `app-buchungsdetail`. 1:1 dasselbe Lade-Muster wie `veranstaltungsdetail.ts` (Story 1.4): `ActivatedRoute.paramMap` → `switchMap` → Service-Call → `catchError` setzt Fehlerzustand:
    ```typescript
    import { CurrencyPipe, DatePipe } from '@angular/common';
    import { Component, inject, signal } from '@angular/core';
    import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
    import { ActivatedRoute } from '@angular/router';
    import { EMPTY, catchError, map, switchMap } from 'rxjs';
    import { BuchungenService } from '../shared/api/buchungen.service';
    import { BuchungDetail } from '../shared/models/buchung-detail';
    import { BadgeStatus } from '../shared/ui/badge-status/badge-status';
    import { Buchungsreferenz } from '../shared/ui/buchungsreferenz/buchungsreferenz';
    import { spielstaettenOffset } from '../shared/utils/zeitzone';

    type Ladezustand = 'laedt' | 'geladen' | 'fehler';

    @Component({
      selector: 'app-buchungsdetail',
      imports: [CurrencyPipe, DatePipe, BadgeStatus, Buchungsreferenz],
      templateUrl: './buchungsdetail.html',
      styleUrl: './buchungsdetail.scss',
    })
    export class Buchungsdetail {
      private readonly buchungenService = inject(BuchungenService);
      private readonly route = inject(ActivatedRoute);

      readonly ladezustand = signal<Ladezustand>('laedt');
      readonly buchung = signal<BuchungDetail | null>(null);

      protected readonly spielstaettenOffset = spielstaettenOffset;

      constructor() {
        this.route.paramMap
          .pipe(
            map((paramMap) => paramMap.get('referenz')!),
            switchMap((referenz) => {
              this.ladezustand.set('laedt');
              return this.buchungenService.buchungAbrufen(referenz).pipe(
                catchError(() => {
                  this.ladezustand.set('fehler');
                  return EMPTY;
                }),
              );
            }),
            takeUntilDestroyed(),
          )
          .subscribe((buchung) => {
            this.buchung.set(buchung);
            this.ladezustand.set('geladen');
          });
      }
    }
    ```
    ```html
    <!-- buchungsdetail.html -->
    @if (ladezustand() === 'laedt') {
      <p class="buchungsdetail__ladehinweis">Buchung wird geladen …</p>
    } @else if (ladezustand() === 'fehler') {
      <p class="buchungsdetail__fehler" role="alert">
        Keine Buchung mit dieser Referenz gefunden.
      </p>
    } @else if (buchung(); as b) {
      <main class="buchungsdetail">
        <h1 class="buchungsdetail__titel">{{ b.veranstaltungTitel }}</h1>
        <app-badge-status [status]="b.status" />
        <app-buchungsreferenz [referenz]="b.referenz" />
        <p class="buchungsdetail__zeitpunkt">
          {{ b.veranstaltungZeitpunkt | date: 'EEEE, d. MMMM y, HH:mm':spielstaettenOffset(b.veranstaltungZeitpunkt) }} Uhr
          · {{ b.spielstaetteName }}, {{ b.raumName }}
        </p>
        <ul class="buchungsdetail__positionen">
          @for (position of b.positionen; track position.sitzplatzCode) {
            <li class="buchungsdetail__position">
              <span class="buchungsdetail__code">{{ position.sitzplatzCode }}</span>
              <span class="buchungsdetail__kategorie">{{ position.preiskategorieName }}</span>
              <span class="buchungsdetail__einzelpreis">{{ position.preisSnapshot | currency: 'EUR' }}</span>
            </li>
          }
        </ul>
        <p class="buchungsdetail__gesamtpreis">Gesamtpreis: {{ b.gesamtpreis | currency: 'EUR' }}</p>
      </main>
    }
