    ```
  - [ ] `buchung-abrufen.spec.ts` (Muster: `veranstaltungsdetail.spec.ts` — `TestBed` + Service-Stub, `provideRouter([])`): Submit-Button bei leerem Feld deaktiviert; bei Fehlschlag (`error: () => throwError(...)`) erscheint `banner-error` mit exaktem Text „Keine Buchung mit dieser Referenz gefunden."; bei Erfolg wird `Router.navigate` mit `['/buchungen', <referenz>]` aufgerufen (`vi.spyOn(TestBed.inject(Router), 'navigate')`).

- [ ] Task 7: Frontend — `Buchungsdetail`-Anzeige-Komponente (AC: #1, #2, #4, #5, #6)
  - [ ] Neue Komponente `seed-a-frontend/src/app/buchung-abrufen/buchungsdetail.ts` (+ `.html`, `.scss`, `.spec.ts`), Selector `app-buchungsdetail`. 1:1 dasselbe Lade-Muster wie `veranstaltungsdetail.ts` (Story 1.4): `ActivatedRoute.paramMap` → `switchMap` → Service-Call → `catchError` setzt Fehlerzustand:
    ```typescript
    import { CurrencyPipe, DatePipe } from '@angular/common';
    import { Component, inject, signal } from '@angular/core';
    import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
    import { ActivatedRoute } from '@angular/router';
    import { EMPTY, catchError, map, switchMap } from 'rxjs';
    import { BuchungenService } from '../shared/api/buchungen.service';
    import { BuchungDetail } from '../shared/models/buchung-detail';
    import { BadgeStatus } from '../shared/ui/badge-status/badge-status';
    import { Buchungsreferenz } from '../shared/ui/buchungsreferenz/buchungsreferenz';
    import { spielstaettenOffset } from '../shared/utils/zeitzone';

    type Ladezustand = 'laedt' | 'geladen' | 'fehler';

    @Component({
      selector: 'app-buchungsdetail',
      imports: [CurrencyPipe, DatePipe, BadgeStatus, Buchungsreferenz],
      templateUrl: './buchungsdetail.html',
      styleUrl: './buchungsdetail.scss',
    })
    export class Buchungsdetail {
      private readonly buchungenService = inject(BuchungenService);
      private readonly route = inject(ActivatedRoute);

      readonly ladezustand = signal<Ladezustand>('laedt');
      readonly buchung = signal<BuchungDetail | null>(null);

      protected readonly spielstaettenOffset = spielstaettenOffset;

      constructor() {
        this.route.paramMap
          .pipe(
            map((paramMap) => paramMap.get('referenz')!),
            switchMap((referenz) => {
              this.ladezustand.set('laedt');
              return this.buchungenService.buchungAbrufen(referenz).pipe(
                catchError(() => {
                  this.ladezustand.set('fehler');
                  return EMPTY;
                }),
              );
            }),
            takeUntilDestroyed(),
          )
          .subscribe((buchung) => {
            this.buchung.set(buchung);
            this.ladezustand.set('geladen');
          });
      }
    }
    ```
    ```html
    <!-- buchungsdetail.html -->
    @if (ladezustand() === 'laedt') {
      <p class="buchungsdetail__ladehinweis">Buchung wird geladen …</p>
    } @else if (ladezustand() === 'fehler') {
      <p class="buchungsdetail__fehler" role="alert">
        Keine Buchung mit dieser Referenz gefunden.
      </p>
    } @else if (buchung(); as b) {
      <main class="buchungsdetail">
        <h1 class="buchungsdetail__titel">{{ b.veranstaltungTitel }}</h1>
        <app-badge-status [status]="b.status" />
        <app-buchungsreferenz [referenz]="b.referenz" />
        <p class="buchungsdetail__zeitpunkt">
          {{ b.veranstaltungZeitpunkt | date: 'EEEE, d. MMMM y, HH:mm':spielstaettenOffset(b.veranstaltungZeitpunkt) }} Uhr
          · {{ b.spielstaetteName }}, {{ b.raumName }}
        </p>
        <ul class="buchungsdetail__positionen">
          @for (position of b.positionen; track position.sitzplatzCode) {
            <li class="buchungsdetail__position">
              <span class="buchungsdetail__code">{{ position.sitzplatzCode }}</span>
              <span class="buchungsdetail__kategorie">{{ position.preiskategorieName }}</span>
              <span class="buchungsdetail__einzelpreis">{{ position.preisSnapshot | currency: 'EUR' }}</span>
            </li>
          }
        </ul>
        <p class="buchungsdetail__gesamtpreis">Gesamtpreis: {{ b.gesamtpreis | currency: 'EUR' }}</p>
      </main>
    }
    ```
    **Warum diese Komponente direkt selbst lädt statt Daten von `BuchungAbrufen` zu übernehmen:** Die Route `/buchungen/:referenz` ist laut `EXPERIENCE.md` Information Architecture eine eigenständige Surface und muss (analog zu `/veranstaltungen/:id`) bei direktem Aufruf/Reload funktionieren — kein Router-State-Passing, das bei Neuladen verloren ginge.
  - [ ] `buchungsdetail.spec.ts` (Muster: `veranstaltungsdetail.spec.ts` — `ActivatedRoute` mit `paramMap: of(convertToParamMap({ referenz: '...' }))`, `provideRouter([])`): zeigt Veranstaltungstitel, Zeitpunkt, Spielstätte/Raum, alle Positionen mit Preiskategorie, Gesamtpreis; zeigt Ladehinweis während `Subject` noch offen; zeigt Fehlermeldung bei `throwError(...)`; rendert `app-badge-status` mit `status="Storniert"` wenn die Buchung storniert ist.

- [ ] Task 8: Frontend — Routing + globale Navigation (AC: #7)
  - [ ] `seed-a-frontend/src/app/app.routes.ts` um zwei Routen ergänzen:
    ```typescript
    { path: 'buchung-abrufen', component: BuchungAbrufen },
    { path: 'buchungen/:referenz', component: Buchungsdetail },
    ```
    Reihenfolge beachten: **vor** `{ path: 'veranstaltungen/:id', ... }`, da Angular-Routen der Reihe nach geprüft werden — `buchungen/:referenz` kollidiert mit keinem bestehenden Pfad-Präfix, Position ist aber unkritisch; `buchung-abrufen` ist ein statischer Pfad und muss nicht vor dynamischen Routen stehen.
  - [ ] `seed-a-frontend/src/app/app.html`: globale Navigation ergänzen (erste Story mit diesem Bedarf — bisher nur `<router-outlet />`):
    ```html
    <header class="app-nav">
      <a class="app-nav__logo" routerLink="/">Sitzplatz-Buchungssystem</a>
      <a class="app-nav__link" routerLink="/buchung-abrufen">Buchung abrufen</a>
    </header>
    <router-outlet />
    ```
  - [ ] `seed-a-frontend/src/app/app.ts`: `RouterLink` zu den `imports` der `App`-Komponente ergänzen (`RouterOutlet` ist bereits vorhanden).
  - [ ] `seed-a-frontend/src/app/app.scss` (aktuell leer) minimal befüllen (Flex-Header, `--spacing-margin-mobile`/`-desktop`, `--font-label-*`-Tokens, analog zu `veranstaltungsdetail.scss`).
  - [ ] **Wichtig — bestehenden Test nicht brechen:** `app.spec.ts` konfiguriert `TestBed` bisher **ohne** Router-Provider. Sobald `app.html` `routerLink` verwendet, benötigt `RouterLink` einen injizierbaren `Router` — ohne Provider schlägt `TestBed.createComponent(App)` fehl. `app.spec.ts` muss `providers: [provideRouter([])]` ergänzen (Muster: `veranstaltungsdetail.spec.ts` Zeile mit `provideRouter([])`).

## Dev Notes

### Bereits etablierte Muster — nicht neu erfinden

- **Route-Lade-Muster mit `ActivatedRoute.paramMap`/`switchMap`/`catchError`:** exakt aus `veranstaltungsdetail.ts` (Story 1.4) übernommen für `Buchungsdetail`.
- **Include+Select-DTO-Projektion im Service:** exakt aus `VeranstaltungenService.GetVeranstaltungAsync` übernommen für `BuchungenService.BuchungAbrufenAsync`.
- **`WebApplicationFactory<Program>`/`HttpClient`-Endpunkttest-Setup:** bereits in `BuchungenEndpointTests.cs` vorhanden — nur neue `[Fact]`s ergänzen, kein neues Setup nötig.
- **Automatische `ProblemDetails`-Umwandlung bei `NotFound()`:** bereits etabliert über `builder.Services.AddProblemDetails()` in `Program.cs`, siehe `VeranstaltungenController.GetVeranstaltung`/`GetSitzplan` — keine manuelle `ProblemDetails`-Konstruktion für den einfachen 404-Fall ohne Zusatzfelder nötig.
- **Deutsches Domänenvokabular durchgängig**: `BuchungAbrufenAsync`, `BuchungDetailDto`, `referenzEingabe`, `Buchungsdetail`, `BuchungAbrufen`, `buchung-abrufen` — keine englischen Bezeichner (Architecture Consistency Conventions).
- **CSS-Custom-Properties-Token-System** aus `styles/_tokens.scss` (Story 1.1) direkt konsumieren, keine neuen Tokens für Standardwerte (Farben, Typografie, Spacing) einführen — nur die dokumentierte `[ASSUMPTION]` zum fehlenden `on-success-container`-Token betrifft `badge-status`.

### Warum diese Story keine Stornierungs-Logik enthält

Story 3.1 deckt ausschließlich FR-12 (Abruf) ab. FR-13 (Stornierung, `POST /buchungen/{referenz}/stornierung`, Bestätigungsdialog, `banner-success`) ist Story 3.2 und **nicht** Teil dieser Story — AC #4 verlangt nur, dass eine bereits stornierte Buchung korrekt (mit `badge-status` „storniert") angezeigt wird, nicht dass eine Stornieren-Aktion existiert. Kein „Stornieren"-Button in `buchungsdetail.html` dieser Story hinzufügen — das käme in Story 3.2 dazu, ohne diese Story vorzugreifen (Architecture Capability Map trennt FR-12 und FR-13 explizit auf unterschiedliche Governed-by-Zeilen).

### Kein neuer Anfangsdatenbestand / keine Migration nötig

Alle für diese Story benötigten Entitäten (`Buchung`, `Buchungsposition`, `Veranstaltung`, `Raum`, `Spielstaette`, `Preiskategorie`) und ihre Beziehungen existieren bereits vollständig (Stories 1.1–2.6). Diese Story fügt ausschließlich einen neuen **Lesezugriff** hinzu — keine Schemaänderung, keine neue EF-Core-Migration.

### Bekannter Grenzfall: keine vorgefertigten `Buchung`-Datensätze im Anfangsdatenbestand

`anfangsdatenbestand.json` enthält für `E1` nur `belegteSitzplaetze` (führt zu `Sitzplatzbelegung`-Zeilen mit `BuchungId = null`, siehe `SeedLoaderTests`), aber **keine** echten `Buchung`-Datensätze. Endpoint-Tests für den Abruf müssen daher zuerst über den bestehenden `POST /veranstaltungen/{id}/buchungen`-Endpunkt eine echte Buchung anlegen (wie ein realer Besucher-Flow), bevor sie sie abrufen — nicht versuchen, eine Referenz aus dem Anfangsdatenbestand zu erraten.

### Project Structure Notes

- Neue Dateien Backend: `seed-a-backend.Api/DTOs/BuchungDetailDto.cs`, `seed-a-backend.Api/Controllers/BuchungenController.cs`.
- Geänderte Dateien Backend: `seed-a-backend.Api/Services/IBuchungenService.cs`, `seed-a-backend.Api/Services/BuchungenService.cs`, `seed-a-backend.Tests/BuchungenServiceTests.cs`, `seed-a-backend.Tests/BuchungenEndpointTests.cs`.
- Neue Dateien Frontend: `seed-a-frontend/src/app/shared/models/buchung-detail.ts`, `seed-a-frontend/src/app/shared/ui/badge-status/{badge-status.ts,badge-status.html,badge-status.scss,badge-status.spec.ts}`, `seed-a-frontend/src/app/buchung-abrufen/{buchung-abrufen.ts,buchung-abrufen.html,buchung-abrufen.scss,buchung-abrufen.spec.ts,buchungsdetail.ts,buchungsdetail.html,buchungsdetail.scss,buchungsdetail.spec.ts}`.
- Geänderte Dateien Frontend: `seed-a-frontend/src/app/shared/api/buchungen.service.ts`, `seed-a-frontend/src/app/app.routes.ts`, `seed-a-frontend/src/app/app.html`, `seed-a-frontend/src/app/app.ts`, `seed-a-frontend/src/app/app.scss`, `seed-a-frontend/src/app/app.spec.ts`.
- Vollständig konform mit `ARCHITECTURE-SPINE.md` Structural Seed: `buchung-abrufen/` ist bereits als Feature-Ordner für „FR-12–FR-13: Referenz-Eingabe, Buchungsdetail, Stornierung" vorgesehen — beide Komponenten dieser Story (Formular + Detailanzeige) leben dort, keine neue Ordnerstruktur nötig. `BuchungenController` liegt flach in `Controllers/`, exakt wie `VeranstaltungenController`.

